import { api } from '../api.js';
import { esc, progress, loading, errorBox } from '../util.js';

// Multiple-choice quiz, generated by the local model (or offline from the dataset).
export function mountQuiz(container, { philosopherId, topicId, title }) {
  container.innerHTML = `
    <div class="row" style="margin-bottom:1rem">
      <label class="small">Questions <select name="count"><option>3</option><option selected>5</option><option>8</option><option>10</option></select></label>
      <label class="small">Difficulty <select name="difficulty"><option>easy</option><option selected>medium</option><option>hard</option></select></label>
      <label class="small"><input type="checkbox" name="offline"> Offline (no AI)</label>
      <button class="btn primary" type="button" data-start>Start quiz</button>
    </div>
    <div class="quiz-body"></div>`;
  const body = container.querySelector('.quiz-body');
  container.querySelector('[data-start]').addEventListener('click', async () => {
    body.innerHTML = loading('Writing questions… (the local model can take a little while)');
    try {
      const data = await api.quiz({
        philosopherId, topicId,
        count: Number(container.querySelector('[name=count]').value),
        difficulty: container.querySelector('[name=difficulty]').value,
        mode: container.querySelector('[name=offline]').checked ? 'offline' : 'ai',
      });
      play(body, data, { philosopherId, topicId, title });
    } catch (err) {
      body.innerHTML = errorBox(err);
    }
  });
}

function play(body, data, ctx) {
  const qs = data.questions;
  if (!qs.length) {
    body.innerHTML = '<p class="muted">Not enough material to build a quiz here yet.</p>';
    return;
  }
  let answered = 0;
  let correct = 0;
  body.innerHTML = `
    <p class="muted small">${data.source === 'ai' ? `Generated by ${esc(data.model)} from the encyclopedia text.` : 'Offline questions from the Philophile dataset.'}</p>
    ${qs.map((q, i) => `
      <div class="quiz-q card" data-i="${i}">
        <strong>${i + 1}. ${esc(q.question)}</strong>
        <ol>${q.options.map((o, j) => `<li><button class="opt" type="button" data-j="${j}">${esc(o)}</button></li>`).join('')}</ol>
        <div class="explain" hidden>${esc(q.explanation)}</div>
      </div>`).join('')}
    <div class="card result" hidden></div>`;

  body.addEventListener('click', (e) => {
    const btn = e.target.closest('button.opt');
    if (!btn) return;
    const box = btn.closest('.quiz-q');
    const q = qs[Number(box.dataset.i)];
    const j = Number(btn.dataset.j);
    box.querySelectorAll('button.opt').forEach((b, k) => {
      b.disabled = true;
      if (k === q.answerIndex) b.classList.add('right');
    });
    if (j === q.answerIndex) correct++;
    else btn.classList.add('wrong');
    box.querySelector('.explain').hidden = false;
    answered++;
    if (answered === qs.length) {
      const result = body.querySelector('.result');
      const pct = Math.round((correct / qs.length) * 100);
      result.hidden = false;
      result.innerHTML = `<div class="score">${correct} / ${qs.length} correct (${pct}%)</div>
        <div class="progress-bar" style="margin:.5rem 0"><i style="width:${pct}%"></i></div>
        <p class="muted small">${pct >= 80 ? 'Excellent — try a harder level.' : pct >= 50 ? 'Good progress. Review the explanations above.' : 'Read the Encyclopedia tab and try again.'}</p>`;
      progress.recordQuiz({ subject: ctx.title, philosopherId: ctx.philosopherId, topicId: ctx.topicId, correct, total: qs.length, source: data.source });
    }
  });
}
